import {config,categories,seedProducts,demoWholesale} from './data.js';
import {totals,csvEscape,parseCSV} from './domain.js';
const $=s=>document.querySelector(s);
const paths={search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bag:'M5 7h14l1 14H4L5 7Z M8 8V6a4 4 0 0 1 8 0v2',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',truck:'M1 4h13v13H1V4Z M14 9h5l4 4v4h-9 M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',snow:'M12 2v20 M3.3 7l17.4 10 M3.3 17L20.7 7 M8 4l4 4 4-4 M8 20l4-4 4 4 M3 11l5-1-1-5 M21 13l-5 1 1 5 M3 13l5 1-1 5 M21 11l-5-1 1-5',store:'M3 10v11h18V10 M2 3h20l1 7a3 3 0 0 1-5 2 3 3 0 0 1-6 0 3 3 0 0 1-6 0 3 3 0 0 1-5-2l1-7Z M9 21v-6h6v6',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z M8 12l3 3 5-6',tag:'M21 12l-9 9L2 11V2h9l10 10Z M7 7h.01',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',close:'M6 6l12 12 M18 6L6 18',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',check:'M5 12l4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',mail:'M2 4h20v16H2V4Z M2 4l10 8L22 4',phone:'M22 16.9v3a2 2 0 0 1-2.2 2 20 20 0 0 1-8.7-3.1 20 20 0 0 1-6.2-6.2A20 20 0 0 1 1.8 4 2 2 0 0 1 3.8 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L7.7 10a16 16 0 0 0 6.3 6.3l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 1.7',grid:'M3 3h7v7H3V3Z M14 3h7v7h-7V3Z M3 14h7v7H3v-7Z M14 14h7v7h-7v-7Z',box:'M21 7l-9-5-9 5v10l9 5 9-5V7Z M3 7l9 5 9-5 M12 12v10 M7.5 4.5l9 5',chart:'M3 3v18h18 M7 16V9 M12 16V5 M17 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 2h6l1 3 3 1 3 3v6l-3 1-1 3-3 3H9l-1-3-3-1-3-3V9l3-1 1-3 3-3Z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',edit:'M16 3l5 5 M3 21l5-1L21 7l-5-5L3 15v6Z',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01',home:'M3 10l9-8 9 8v12h-7v-8h-4v8H3V10Z',repeat:'M3 7h15l3 3 M18 4l3 3-3 3 M21 17H6l-3-3 M6 20l-3-3 3-3',star:'M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',lock:'M5 10h14v12H5V10Z M8 10V6a4 4 0 0 1 8 0v4',logout:'M9 3H3v18h6 M10 12h12 M18 8l4 4-4 4'};
const icon=(name,cls='')=>`<svg aria-hidden="true" class="${cls}" viewBox="0 0 24 24"><path d="${paths[name]||paths.box}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
const date=d=>new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(d));
const STORE='libertad-demo-v1';let storageOK=true;
function read(){try{return JSON.parse(localStorage.getItem(STORE)||'null')}catch{return null}}
const saved=read();
let state={products:structuredClone(seedProducts),settings:structuredClone(config),cart:[],favorites:[],profile:null,addresses:[],orders:[],wholesale:structuredClone(demoWholesale),audit:[],coupon:'',...saved};
// New configuration keys remain available when an earlier demo is reopened.
state.settings={...config,...state.settings,contact:{...config.contact,...state.settings?.contact}};
function save(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch{storageOK=false;toast('No se pudo guardar. Revisá el espacio disponible del navegador.')}}
let pageLimit=9,toastTimer,returnFocus=null,drawerOpen=false;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function audit(action){state.audit.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),actor:state.profile?.name||'Operador DEMO',action});state.audit=state.audit.slice(0,250)}
function route(){const raw=location.hash.slice(1)||'/';const [path,query]=raw.split('?');return{path,params:new URLSearchParams(query||'')}}
function goto(url){if(location.hash==='#'+url)render();else location.hash=url;}
function isWholesale(){return state.profile&&state.wholesale.some(w=>w.email===state.profile.email&&w.status==='Aprobada')}
function calc(delivery='pickup'){return totals(state.cart,state.products,state.settings,{delivery,coupon:state.coupon,wholesale:isWholesale()})}
function brand(){return `<a class="brand" href="#/" aria-label="Distribuidora Libertad, inicio"><img src="/assets/logo.svg" alt="Logotipo provisional"><span class="brand-type"><small>DISTRIBUIDORA</small><strong>LIBERTAD</strong></span></a>`}
function header(){const {path}=route();const active=p=>path===p?'active':'';return `<div class="topbar"><div class="container"><span class="location">${icon('pin')}Santiago del Estero · Argentina</span><span><b class="demo-tag">DEMO</b> Un adelanto de algo muy rico. Productos y precios de ejemplo.</span></div></div><header class="header"><div class="container"><div class="header-main">${brand()}<form class="search" data-form="search" role="search"><input name="q" placeholder="¿Qué helado tenés ganas de probar?" aria-label="Buscar helados" value="${esc(route().params.get('q')||'')}"><button aria-label="Buscar" type="submit">${icon('search')}</button></form><div class="header-tools"><a class="tool favorites-tool" href="#/cuenta?tab=favoritos" aria-label="Mis favoritos">${icon('heart')}</a><a class="tool" href="#/cuenta">${icon('user')}<span class="tool-text"><small>¡Hola${state.profile?', '+esc(state.profile.name.split(' ')[0]):''}!</small><strong>Mi cuenta</strong></span></a><button class="tool" data-action="cart" aria-label="Abrir carrito, ${calc().count} productos"><span class="cart-icon">${icon('bag')}<span class="count">${calc().count}</span></span><span class="tool-text"><small>Tu pedido</small><strong>${money(calc().total)}</strong></span></button></div></div><nav class="navigation" aria-label="Navegación principal"><div class="nav-inner"><div class="nav-links"><a href="#/" class="${active('/')}">Inicio</a><a href="#/tienda" class="${active('/tienda')}">Todos los helados</a><a href="#/ofertas" class="offer ${active('/ofertas')}">${icon('tag')}Ofertas</a><a href="#/nosotros" class="${active('/nosotros')}">Sobre nosotros</a><a href="#/contacto" class="${active('/contacto')}">Contacto</a></div><a class="wholesale-link" href="#/mayoristas">${icon('store')}¿Tenés un comercio? ${icon('arrow')}</a></div></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p>Un mundo de helados.<br>Muchos momentos para compartir.</p><div class="footer-note">${icon('pin')}Santiago del Estero, Argentina</div></div><div><h4>Encontrá tu favorito</h4><div class="footer-links"><a href="#/tienda">Todos los helados</a><a href="#/ofertas">Ofertas y combos</a><a href="#/mayoristas">Venta mayorista</a><a href="#/cuenta?tab=favoritos">Mis favoritos</a></div></div><div><h4>Estamos cerca</h4><div class="footer-links"><a href="#/nosotros">Sobre nosotros</a><a href="#/contacto">Contacto y ubicación</a><a href="#/ayuda">Preguntas frecuentes</a><a href="#/legal">Privacidad y condiciones DEMO</a><a href="/proyecto-libertad-demo.zip" download>Descargar código y documentación</a></div></div><div><h4>Una tienda en construcción</h4><div class="footer-links"><span>Identidad y catálogo provisionales.</span><span>Sin pagos ni envíos reales.</span><a href="#/admin">Explorar panel DEMO ${icon('arrow')}</a><button class="text-link" style="border:0;background:none;padding:0;text-align:left" data-action="demo-info">¿Cómo funciona esta versión?</button></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Distribuidora Libertad · Propuesta visual provisional.</span><span>Productos, precios, imágenes y condiciones ilustrativos. No habilitado para ventas reales.</span></div></div></footer>`}
function mobileNav(){const {path}=route();return `<nav class="mobile-nav" aria-label="Accesos móviles"><a href="#/" class="${path==='/'?'active':''}">${icon('home')}Inicio</a><a href="#/tienda" class="${path==='/tienda'?'active':''}">${icon('grid')}Helados</a><a href="#/ofertas" class="${path==='/ofertas'?'active':''}">${icon('tag')}Ofertas</a><button data-action="cart" aria-label="Carrito, ${calc().count} productos">${icon('bag')}Carrito (${calc().count})</button><a href="#/cuenta" class="${path==='/cuenta'?'active':''}">${icon('user')}Mi cuenta</a></nav>`}
function productCard(p){return `<article class="product"><button class="fav ${state.favorites.includes(p.id)?'selected':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Quitar de':'Agregar a'} favoritos: ${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button><a class="product-image" href="#/producto/${p.id}">${p.badge?`<span class="badge ${!p.oldPrice?'blue':''}">${esc(p.badge)}</span>`:''}<img src="${esc(p.image)}" alt="Imagen ilustrativa: ${esc(p.name)}" loading="lazy" width="400" height="400"></a><div class="product-body"><div class="product-brand">${esc(p.brand)} · DEMO</div><h3><a href="#/producto/${p.id}">${esc(p.name)}</a></h3><div class="product-size">${esc(p.size)}</div><div class="product-bottom"><div class="price"><strong>${money(p.price)}</strong>${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}<small>Precio minorista DEMO</small></div><button class="add" data-action="add" data-id="${p.id}" ${p.stock<1?'disabled':''} aria-label="Agregar ${esc(p.name)} al carrito">${icon('plus')}${p.stock?'Agregar':'Agotado'}</button></div></div></article>`}
function sectionTitle(kicker,title,desc,link,label){return `<div class="section-head"><div>${kicker?`<div class="section-kicker">${kicker}</div>`:''}<h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${link?`<a class="text-link" href="#${link}">${label||'Ver todos'} ${icon('arrow')}</a>`:''}</div>`}
function home(){const featured=state.products.filter(p=>p.featured&&p.active).slice(0,4);return `<section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> UN MUNDO DE HELADOS, CERCA TUYO</div><h1>Más helados.<br>Más momentos<br><em>felices.</em></h1><p>Para darte un gusto, compartir en familia<br>o llenar de sabor tu comercio.</p><div class="hero-actions"><a class="btn" href="#/tienda">Encontrá tu helado ${icon('arrow')}</a><a class="btn secondary" href="#/ofertas">Ver ofertas</a></div><div class="hero-note"><span>${icon('truck')}Entrega a domicilio</span><span>${icon('store')}Retiro en el local</span></div></div><div class="hero-visual"><img class="hero-photo" src="/assets/frutilla.jpg" alt="Cucurucho con helado de frutilla y crema sobre un fondo amarillo" fetchpriority="high" width="700" height="1050"><div class="hero-stamp"><span>Un gustito</span><strong>siempre</strong><span>viene bien</span></div><div class="floating-label"><span class="round">${icon('heart')}</span><div><strong>Para todos los gustos</strong><small>Elegí tu próximo favorito</small></div></div><span class="spark" aria-hidden="true">✳</span></div></div></section><section class="benefits" aria-label="Modalidades previstas"><div class="container benefits-inner">${[['truck','Hasta tu puerta','Cobertura local de ejemplo'],['snow','Bien fríos, bien ricos','La cadena de frío es prioridad'],['store','Para vos y tu comercio','Opciones minoristas y mayoristas'],['bag','Comprá a tu manera','Envío o retiro · Modalidad DEMO']].map(([i,t,d])=>`<div class="benefit">${icon(i)}<div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}</div></section><div class="container"><section class="section">${sectionTitle('', 'Un helado para cada momento','¿Con cuál te tentás hoy?','/tienda','Explorar catálogo')}<div class="category-grid">${categories.slice(1).map(c=>`<a class="category-card" style="--cat-bg:${c.color}" href="#/tienda?cat=${c.id}"><img src="/assets/${c.image}.jpg" alt="" loading="lazy" width="100" height="100"><strong>${c.name}</strong><small>${c.subtitle}</small></a>`).join('')}</div></section><section class="section">${sectionTitle('ES DIFÍCIL ELEGIR SOLO UNO','Los favoritos de siempre','Sabores que dan ganas de repetir.','/tienda','Ver todos los helados')}<div class="product-grid">${featured.map(productCard).join('')}</div></section><div class="promo-row"><section class="promo"><div class="copy"><div class="section-kicker">MÁS SABOR, MENOS PRECIO</div><h3>Los gustitos<br>también tienen oferta.</h3><a href="#/ofertas" class="text-link">Descubrí las promos ${icon('arrow')}</a><p style="margin-top:10px;font-size:9px">Promociones y precios DEMO.</p></div><img src="/assets/dulce.jpg" alt="Palitos helados de frutos rojos" loading="lazy"></section><section class="promo blue"><div class="copy"><div class="section-kicker" style="color:var(--blue)">EL PLAN PERFECTO</div><h3>Para compartir.<br>O no tanto.</h3><a href="#/tienda?cat=familiares" class="text-link">Elegí tu pote familiar ${icon('arrow')}</a></div><img src="/assets/vainilla.jpg" alt="Porciones de helado cremoso servidas en una copa" loading="lazy"></section></div><section class="wholesale-banner"><div><div class="section-kicker">HAGAMOS CRECER TU COMERCIO</div><h2>El mejor aliado de tu freezer.</h2><p>Presentaciones grandes y condiciones pensadas para comercios.<br>Solicitá tu cuenta y explorá la experiencia mayorista DEMO.</p></div><a href="#/mayoristas" class="btn white">Quiero comprar por mayor ${icon('arrow')}</a></section><div class="brands" aria-label="Marcas ficticias de demostración"><span>nube®</span><span>Cremolino</span><span>BRISA FRÍA</span><small>Marcas ficticias · DEMO</small></div></div>`}
function crumb(label){return `<div class="breadcrumb"><a href="#/">Inicio</a>${icon('chevron')}<span>${esc(label)}</span></div>`}
function pageHead(title,desc=''){return `<div class="page-title"><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`}
function notice(text,type=''){return `<div class="notice ${type}">${icon('info')}<div>${text}</div></div>`}
function empty(title,desc,link='/tienda',label='Explorar helados',i='bag'){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${desc}</p>${link?`<a class="btn" href="#${link}">${label} ${icon('arrow')}</a>`:''}</div>`}
function catalog(offers=false){const {params}=route();let list=state.products.filter(p=>p.active);const cat=params.get('cat')||'todos',q=params.get('q')||'',brandFilter=params.get('brand')||'',flavor=params.get('flavor')||'',sort=params.get('sort')||'featured';if(offers)list=list.filter(p=>p.oldPrice);if(cat!=='todos')list=list.filter(p=>p.category===cat);if(q){const needle=q.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();list=list.filter(p=>[p.name,p.brand,p.flavor,p.size].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(needle))}if(brandFilter)list=list.filter(p=>p.brand===brandFilter);if(flavor)list=list.filter(p=>p.flavor===flavor);if(params.get('stock'))list=list.filter(p=>p.stock>0);if(sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));if(sort==='featured')list.sort((a,b)=>Number(!!b.featured)-Number(!!a.featured));const option=(v,label)=>`<option value="${esc(v)}" ${sort===v?'selected':''}>${label}</option>`;const base=offers?'/ofertas':'/tienda';const brands=[...new Set(state.products.map(p=>p.brand))],flavors=[...new Set(state.products.map(p=>p.flavor))];return `<div class="container">${crumb(offers?'Ofertas':'Todos los helados')}${pageHead(offers?'Gustitos a precios felices.':'Encontrá tu próximo favorito.',offers?'Descuentos, combos y más oportunidades para compartir. Todas las condiciones son DEMO.':'Un mundo de sabores, tamaños y momentos para disfrutar. Todos los precios son de demostración.')}${offers?notice(`Probá el cupón <strong>${esc(state.settings.coupon)}</strong>: ${Math.round(state.settings.couponDiscount*100)}% de descuento desde ${money(state.settings.couponMin)}. Acumulable con el descuento por cantidad · DEMO.`):''}<div class="chips">${categories.map(c=>`<a class="chip ${cat===c.id?'active':''}" href="#${base}${c.id!=='todos'?'?cat='+c.id:''}">${c.id==='todos'?icon('grid'):''}${c.id==='todos'?'Todos':c.name}</a>`).join('')}</div><div class="catalog-layout"><aside class="filters"><h3>Elegí a tu gusto</h3><form data-form="filters" data-base="${base}"><input type="hidden" name="cat" value="${esc(cat)}"><label class="field"><span>Buscar</span><input name="q" placeholder="Nombre o sabor" value="${esc(q)}"></label><label class="field"><span>Marca</span><select name="brand"><option value="">Todas las marcas</option>${brands.map(b=>`<option ${b===brandFilter?'selected':''}>${esc(b)}</option>`).join('')}</select></label><label class="field"><span>Sabor</span><select name="flavor"><option value="">Todos los sabores</option>${flavors.map(f=>`<option ${f===flavor?'selected':''}>${esc(f)}</option>`).join('')}</select></label><input type="hidden" name="sort" value="${esc(sort)}"><label class="check"><input type="checkbox" name="stock" value="1" ${params.get('stock')?'checked':''}>Solo disponibles</label><button class="btn small full" type="submit">Aplicar filtros</button><a href="#${base}" class="text-link clear-filters" style="justify-content:center;margin-top:12px">Limpiar filtros</a></form></aside><div class="catalog-main"><div class="results-bar"><span>${list.length} ${list.length===1?'helado':'helados'}${q?' para “'+esc(q)+'”':''}</span><label>Ordenar: <select aria-label="Ordenar productos" data-change="sort">${option('featured','Recomendados')}${option('price-asc','Menor precio')}${option('price-desc','Mayor precio')}${option('name','Nombre A–Z')}</select></label></div>${list.length?`<div class="product-grid">${list.slice(0,pageLimit).map(productCard).join('')}</div>${list.length>pageLimit?`<div class="load-more"><button class="btn secondary" data-action="load">Ver más helados ${icon('plus')}</button><p class="fine">${Math.min(pageLimit,list.length)} de ${list.length} productos</p></div>`:''}`:empty('No encontramos ese sabor.','Probá otra búsqueda o quitá alguno de los filtros.',base,'Ver todo el catálogo','search')}</div></div></div>`}
function detail(id){const p=state.products.find(p=>p.id===id&&p.active);if(!p)return `<div class="container">${crumb('Producto no disponible')}${empty('Este helado no está disponible.','Volvé al catálogo para encontrar otros sabores.')}</div>`;const related=state.products.filter(x=>x.active&&x.id!==p.id&&(x.category===p.category||x.flavor===p.flavor)).slice(0,4);return `<div class="container">${crumb(p.name)}<div class="product-detail"><div class="detail-photo"><img src="${esc(p.image)}" alt="Imagen representativa del sabor ${esc(p.flavor)}" width="700" height="700"><small>Fotografía ilustrativa del sabor servido. Envase y producto DEMO.</small></div><div class="detail-info"><div class="product-brand">${esc(p.brand)} · MARCA FICTICIA</div><h1>${esc(p.name)}</h1><div class="product-size">${esc(p.size)} · Sabor ${esc(p.flavor)}</div><div class="price"><strong>${money(p.price)}</strong>${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}<small>Precio minorista de demostración · ARS</small></div><div class="stock ${!p.stock?'out':''}">${p.stock?'Disponible · '+p.stock+' unidades DEMO':'Sin stock DEMO'}</div><p>${esc(p.description)}</p><form data-form="add-product" data-id="${p.id}" class="purchase-row"><div class="quantity"><button type="button" data-action="detail-minus" aria-label="Reducir cantidad">${icon('minus')}</button><input aria-label="Cantidad" name="qty" id="detail-qty" type="number" min="1" max="${p.stock||1}" value="1" required><button type="button" data-action="detail-plus" data-max="${p.stock}" aria-label="Aumentar cantidad">${icon('plus')}</button></div><button class="btn" ${!p.stock?'disabled':''}>${icon('bag')}Agregar al carrito</button><button type="button" class="btn secondary" data-action="favorite" data-id="${p.id}" aria-label="Guardar favorito">${icon('heart')}</button></form>${isWholesale()?notice(`Cuenta mayorista DEMO aprobada: ${money(p.wholesale)} por unidad desde ${state.settings.wholesaleMin} unidades del mismo producto. El carrito aplica la escala automáticamente.`):`<a href="#/mayoristas" class="text-link">${icon('store')}¿Comprás para tu comercio? Conocé la modalidad mayorista ${icon('arrow')}</a>`}<div class="detail-meta mt"><div>${icon('truck')} Entrega o retiro<strong>Condiciones DEMO configurables</strong></div><div>${icon('snow')} Producto congelado<strong>Conservación pendiente de ficha técnica</strong></div></div></div></div>${notice('Ingredientes, alérgenos, contenido neto y conservación específica deben confirmarse con las fichas del proveedor antes de vender. No uses este catálogo para decidir sobre alergias.','warning')}${related.length?`<section class="section">${sectionTitle('SEGUÍ TENTÁNDOTE','También te pueden gustar','','/tienda','Ver catálogo')}<div class="product-grid">${related.map(productCard).join('')}</div></section>`:''}</div>`}
function quantity(id,qty){return `<div class="quantity"><button data-action="qty" data-id="${id}" data-delta="-1" aria-label="Reducir cantidad">${icon('minus')}</button><span>${qty}</span><button data-action="qty" data-id="${id}" data-delta="1" aria-label="Aumentar cantidad">${icon('plus')}</button></div>`}
function cartLines(){return calc().lines.map(p=>`<div class="cart-line"><a href="#/producto/${p.id}" data-action="close-link"><img src="${esc(p.image)}" alt="${esc(p.name)}"></a><div class="cart-line-content"><h3><a href="#/producto/${p.id}" data-action="close-link">${esc(p.name)}</a></h3><small>${esc(p.size)} · ${money(p.unit)} c/u</small><div class="cart-line-actions">${quantity(p.id,p.qty)}<button class="icon-btn" data-action="remove" data-id="${p.id}" aria-label="Quitar ${esc(p.name)}">${icon('trash')}</button></div></div><div class="line-price">${money(p.total)}</div></div>`).join('')}
function summary(delivery='pickup',couponForm=true){const t=calc(delivery);return `<div class="summary-row"><span>Subtotal (${t.count} unidades)</span><strong>${money(t.subtotal)}</strong></div>${t.volume?`<div class="summary-row discount"><span>Descuento por cantidad DEMO</span><strong>−${money(t.volume)}</strong></div>`:''}${t.couponDiscount?`<div class="summary-row discount"><span>Cupón ${esc(state.coupon)}</span><strong>−${money(t.couponDiscount)}</strong></div>`:''}<div class="summary-row"><span>${delivery==='pickup'?'Retiro en el local':'Entrega DEMO'}</span><strong>${t.shipping?money(t.shipping):'Sin cargo'}</strong></div><div class="summary-row total"><span>Total DEMO</span><strong>${money(t.total)}</strong></div>${couponForm?`<form class="inline-input" data-form="coupon"><input name="coupon" aria-label="Código de descuento" placeholder="¿Tenés un cupón?" value="${esc(state.coupon)}"><button class="btn small secondary">Aplicar</button></form>`:''}<p class="summary-note">Importes de ejemplo en pesos argentinos. ${delivery==='pickup'?'El envío se calcula al elegir entrega.':''} No se realizará ningún cobro.</p>`}
function cartPage(){const t=calc();return `<div class="container">${crumb('Tu carrito')}${pageHead('Un carrito lleno de cosas ricas.','Revisá tu selección antes de continuar. Compra de demostración, sin cobros.')}${!t.count?empty('Todavía no elegiste tu gustito.','Encontrá un helado para vos o para compartir.'): `<div class="two-columns"><div><div class="panel">${cartLines()}</div><a href="#/tienda" class="text-link">Seguir eligiendo helados ${icon('arrow')}</a><div class="notice mt">${icon('tag')}<span>Desde ${state.settings.volumeQty} unidades combinadas: ${Math.round(state.settings.volumeDiscount*100)}% de descuento DEMO. Envío de ejemplo sin cargo desde ${money(state.settings.freeShipping)} de subtotal.</span></div></div><aside><div class="panel"><h2>Tu pedido</h2>${summary()}<a href="#/checkout" class="btn full">Continuar con el pedido ${icon('arrow')}</a></div>${notice('Los precios y el stock se vuelven a validar al confirmar el pedido DEMO.')}</aside></div>`}</div>`}
function checkout(){if(!calc().count)return `<div class="container">${crumb('Checkout')}${empty('Tu carrito está vacío.','Agregá un producto para probar el checkout.')}</div>`;const p=state.profile||{};return `<div class="container">${crumb('Finalizar pedido')}<div class="steps"><a href="#/carrito">1. Tu carrito</a>${icon('chevron')}<strong>2. Datos y entrega</strong>${icon('chevron')}<span>3. Confirmación DEMO</span></div>${pageHead('Ya casi es hora del helado.','Completá este recorrido con datos de ejemplo. Este formulario no envía información al negocio.')}${notice('Entorno de pruebas: usá datos ficticios. El pedido se guarda únicamente en este navegador y no reserva mercadería real.','warning')}<form data-form="checkout" id="checkout-form"><div class="two-columns"><div><section class="panel"><h2>¿Quién recibe?</h2><div class="form-grid">${field('Nombre y apellido','name',p.name||'','text',true)}${field('Correo de ejemplo','email',p.email||'','email',true,'tu-nombre@example.invalid')}${field('Referencia de contacto DEMO','contact','','text',true,'Ej.: CLIENTE-DEMO-01')}<label class="field"><span>Dirección guardada DEMO</span><select data-change="address"><option value="">Completar manualmente</option>${state.addresses.map((a,i)=>`<option value="${i}">${esc(a.label)} · ${esc(a.street)}</option>`).join('')}</select></label></div></section><section class="panel"><h2>¿Cómo lo preferís?</h2><label class="selection"><input type="radio" name="delivery" value="pickup" checked><div><strong>Retiro en el local DEMO</strong><small>Sin cargo · Dirección y horarios pendientes de confirmar.</small></div></label><label class="selection"><input type="radio" name="delivery" value="delivery"><div><strong>Entrega a domicilio DEMO</strong><small>${money(state.settings.shipping)} · Sin cargo desde ${money(state.settings.freeShipping)} de subtotal.</small></div></label><div id="delivery-fields" class="hide mt"><div class="form-grid">${field('Calle y número DEMO','street','','text',false,'Ej.: Calle de Ejemplo 123')}<label class="field"><span>Zona de cobertura DEMO</span><select name="zone"><option value="">Elegí una zona</option>${state.settings.coverage.map(z=>`<option>${esc(z)}</option>`).join('')}<option value="outside">Fuera de cobertura</option></select></label>${field('Referencia','reference','','text',false,'Ej.: portón azul')}</div><p class="fine">Estas zonas no representan cobertura real. La dirección comercial se confirmará antes de operar.</p></div><label class="field mt"><span>Observaciones de ejemplo (opcional)</span><textarea name="notes" maxlength="500" placeholder="Algo que debamos saber para esta prueba"></textarea></label></section><section class="panel"><h2>Método de pago</h2><label class="selection"><input type="radio" checked name="payment" value="demo"><div><strong>Pedido DEMO · Sin cobro</strong><small>Estado: no procesado. No se solicita dinero ni información de tarjeta.</small></div></label><p class="fine">Mercado Pago, tarjetas y transferencias están pendientes de integración. No hay datos bancarios habilitados.</p></section></div><aside><div class="panel"><h2>Resumen de tu pedido</h2><div style="margin-bottom:22px">${calc().lines.map(l=>`<div class="summary-row"><span>${l.qty} × ${esc(l.name)}</span><strong>${money(l.total)}</strong></div>`).join('')}</div><div id="checkout-summary">${summary('pickup',false)}</div><label class="check"><input type="checkbox" name="consent" required>Entiendo que es una prueba sin compra, cobro ni entrega real.</label><button class="btn full" type="submit">Crear pedido DEMO ${icon('arrow')}</button><p class="fine">Se guardará localmente. Podés borrar los datos desde Mi cuenta.</p></div><div id="checkout-error" role="alert" class="inline-error"></div></aside></div></form></div>`}
function field(label,name,value='',type='text',required=false,placeholder=''){return `<label class="field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}" ${type==='number'?'min="0" step="1"':''} maxlength="${type==='email'?254:150}"></label>`}
function confirmation(id){const o=state.orders.find(o=>o.id===id);if(!o)return `<div class="container">${crumb('Pedido')}${empty('No encontramos este pedido en este navegador.','Los pedidos DEMO se guardan en el dispositivo en el que se crean.','/cuenta?tab=pedidos','Ver mis pedidos')}</div>`;return `<div class="container">${crumb('Confirmación DEMO')}<div class="success"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="justify-content:center">RECORRIDO COMPLETADO</div><h1>¡Tu pedido DEMO está guardado!</h1><p class="muted">Probaste la experiencia de compra. No se envió al negocio<br>y no se realizó ningún cobro.</p><div class="panel"><div class="order-header"><h3>${esc(o.number)}</h3><span class="pill orange">Sin pago procesado</span></div><p class="fine">${date(o.created)}</p>${o.lines.map(l=>`<div class="summary-row"><span>${l.qty} × ${esc(l.name)}</span><strong>${money(l.total)}</strong></div>`).join('')}<div class="summary-row"><span>Modalidad</span><strong>${o.delivery==='pickup'?'Retiro DEMO':'Entrega DEMO'}</strong></div><div class="summary-row total"><span>Total de ejemplo</span><strong>${money(o.total)}</strong></div><p class="fine">Estado del pedido: ${esc(o.status)} · Sin reserva de stock comercial.</p></div><div class="hero-actions"><a class="btn" href="#/cuenta?tab=pedidos">Ver mis pedidos ${icon('arrow')}</a><a class="btn secondary" href="#/tienda">Seguir explorando</a></div></div></div>`}
function wholesale(){const request=state.profile?state.wholesale.find(w=>w.email===state.profile.email):null;return `<div class="container">${crumb('Para comercios')}<div class="about-hero"><div><div class="eyebrow"><span class="dot"></span>CRECEMOS CON TU COMERCIO</div><h1>Tu freezer lleno.<br>Tu negocio, también.</h1><p>Una experiencia pensada para kioscos, almacenes y heladerías: presentaciones grandes, recompra rápida y precios especiales para cuentas aprobadas.</p><a class="btn" href="#/tienda?cat=comercios">Ver presentaciones ${icon('arrow')}</a></div><img src="/assets/comercio.jpg" alt="Helado de crema con granas, imagen ilustrativa" loading="lazy"></div>${notice('Las condiciones mayoristas son exclusivamente de demostración. No representan una oferta comercial confirmada.')}<div class="info-grid">${[['user','1. Solicitá tu cuenta','Completá el perfil DEMO y los datos ficticios de tu comercio.'],['check','2. Revisión administrativa','Probá la aprobación o el rechazo desde el panel DEMO.'],['tag','3. Accedé a tus precios','Una cuenta aprobada utiliza precios mayoristas a partir del mínimo configurado.']].map(([i,t,d])=>`<div class="info-card">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="two-columns"><section class="panel"><h2>Solicitud mayorista DEMO</h2>${request?`<div class="row"><strong>${esc(request.business)}</strong>${statusPill(request.status)}</div><p class="fine">La solicitud está ${esc(request.status.toLowerCase())}. Podés probar sus cambios de estado en el panel administrativo DEMO.</p><a href="#/admin/clientes" class="btn secondary small">Ver solicitudes ${icon('arrow')}</a>`:!state.profile?`<p class="muted">Primero creá un perfil de prueba. No necesitás una contraseña y no se abre una cuenta comercial.</p><a href="#/cuenta" class="btn">Crear perfil DEMO ${icon('arrow')}</a>`:`<form data-form="wholesale"><div class="form-grid">${field('Nombre comercial ficticio','business','','text',true,'Ej.: Kiosco DEMO')}${field('Rubro','businessType','','text',true,'Ej.: kiosco')}${field('Referencia fiscal DEMO (sin CUIT real)','taxRef','','text',true,'Ej.: CUIT-DEMO')}${field('Zona de ejemplo','zone','','text',true,'Ej.: Centro DEMO')}</div><label class="check"><input type="checkbox" required>La información es ficticia y comprendo el carácter de prueba.</label><button class="btn">Enviar solicitud DEMO ${icon('arrow')}</button></form>`}</section><aside class="panel"><h2>Condiciones de ejemplo</h2><div class="summary-row"><span>Mínimo por producto para precio mayorista</span><strong>${state.settings.wholesaleMin} unidades</strong></div><div class="summary-row"><span>Escala adicional por carrito</span><strong>${Math.round(state.settings.volumeDiscount*100)}% desde ${state.settings.volumeQty} unidades</strong></div><p class="fine">Parámetros editables desde Configuración. La aprobación DEMO solo afecta este navegador. Para producción se requiere autorización del servidor.</p></aside></div></div>`}
function statusPill(status){return `<span class="pill ${['Aprobada','Entregado DEMO'].includes(status)?'green':['Rechazada','Suspendida','Cancelado DEMO'].includes(status)?'red':'orange'}">${esc(status)}</span>`}
function orderCard(o,admin=false){return `<article class="order-card"><div class="order-header"><div><h3><a href="#/pedido/${o.id}">${esc(o.number)}</a></h3><small class="muted">${date(o.created)}</small></div>${statusPill(o.status)}</div><div class="order-items">${o.lines.map(l=>`${l.qty} × ${esc(l.name)}`).join(' · ')}</div>${admin?`<p class="fine">${esc(o.customer.name)} · ${esc(o.customer.email)}<br>${o.delivery==='delivery'?'Entrega: '+esc(o.customer.street)+' · '+esc(o.customer.zone):'Retiro en el local DEMO'}<br>Contacto: ${esc(o.customer.contact)}${o.customer.notes?'<br>Observaciones: '+esc(o.customer.notes):''}</p>`:''}<div class="order-footer"><strong>${money(o.total)}</strong>${admin?`<select data-change="order-status" data-id="${o.id}" aria-label="Estado de ${esc(o.number)}">${['Recibido DEMO','En preparación DEMO','Listo para retirar DEMO','En reparto DEMO','Entregado DEMO','Cancelado DEMO'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select>`:`<button class="btn small secondary" data-action="reorder" data-id="${o.id}">${icon('repeat')}Volver a pedir</button>`}</div><p class="fine">Pago: no procesado · Pedido de prueba, sin efectos comerciales.</p></article>`}
function account(){const tab=route().params.get('tab')||'perfil';const tabs=[['perfil','Mi perfil'],['pedidos','Mis pedidos'],['favoritos','Mis favoritos'],['direcciones','Direcciones']];const mine=state.profile?state.orders.filter(o=>o.customer.email===state.profile.email):state.orders;let content='';if(tab==='favoritos'){const products=state.products.filter(p=>p.active&&state.favorites.includes(p.id));content=products.length?`<div class="product-grid">${products.map(productCard).join('')}</div>`:empty('Los favoritos se guardan acá.','Tocá el corazón de los helados que más te gusten.','/tienda','Encontrar favoritos','heart')}else if(tab==='pedidos'){content=mine.length?mine.map(o=>orderCard(o)).join(''):empty('Todavía no hay pedidos.','Completá una compra de prueba para explorar tu historial.')}else if(tab==='direcciones'){content=`<div class="two-columns"><div>${state.addresses.length?state.addresses.map((a,i)=>`<div class="panel"><div class="order-header"><h3>${esc(a.label)}</h3><button class="icon-btn" data-action="delete-address" data-index="${i}" aria-label="Eliminar dirección ${esc(a.label)}">${icon('trash')}</button></div><p class="fine">${esc(a.street)}<br>${esc(a.zone)}</p></div>`).join(''):notice('Guardá una dirección ficticia para probar el checkout más rápido.')}</div><form class="panel" data-form="address"><h2>Nueva dirección DEMO</h2>${field('Nombre de referencia','label','','text',true,'Ej.: Casa DEMO')}${field('Calle y número ficticios','street','','text',true,'Ej.: Calle de Ejemplo 123')}<label class="field"><span>Zona de prueba</span><select name="zone">${state.settings.coverage.map(z=>`<option>${esc(z)}</option>`).join('')}</select></label><button class="btn">Guardar dirección</button></form></div>`}else{content=`<div class="two-columns"><form class="panel" data-form="profile"><h2>${state.profile?'Tu perfil de prueba':'¡Hola! Probá tu cuenta.'}</h2><p class="fine">Este es un perfil local DEMO, sin contraseña ni autenticación comercial. No uses datos personales reales.</p>${field('Nombre de ejemplo','name',state.profile?.name||'','text',true,'Ej.: Cliente DEMO')}${field('Correo de ejemplo','email',state.profile?.email||'','email',true,'Ej.: cliente@example.invalid')}<button class="btn">${state.profile?'Guardar cambios':'Crear perfil DEMO'} ${icon('arrow')}</button>${state.profile?`<button class="btn secondary small" style="margin-left:8px" type="button" data-action="logout">Cerrar perfil</button>`:''}</form><div><div class="panel"><h2>Tu experiencia, a mano</h2><p class="fine">Guardá favoritos, direcciones y pedidos en este navegador. Borrar los datos del sitio o cambiar de dispositivo elimina el acceso a esta información.</p><div class="summary-row"><span>Tipo de cuenta de prueba</span>${statusPill(isWholesale()?'Mayorista aprobada':'Minorista DEMO')}</div><a class="text-link" href="#/mayoristas">Solicitar acceso mayorista ${icon('arrow')}</a></div><div class="panel"><h3>Control de datos DEMO</h3><p class="fine">Descargá tu prueba o eliminá todos los datos locales, incluidas las modificaciones del panel.</p><div class="row"><button class="btn small secondary" data-action="export-backup" type="button">${icon('download')}Exportar copia DEMO</button><button class="btn small secondary" data-action="reset" type="button">Restablecer demo</button></div></div></div></div>`}return `<div class="container">${crumb('Mi cuenta')}${pageHead(state.profile?'Hola, '+esc(state.profile.name.split(' ')[0])+'.':'Tu rincón más rico.','Un espacio de demostración para probar tu próxima experiencia de compra.')}${notice('Los perfiles, pedidos y favoritos de esta versión viven en este dispositivo. El acceso comercial con contraseña y los permisos del servidor están pendientes de integración.')}<nav class="tabs" aria-label="Secciones de mi cuenta">${tabs.map(([id,label])=>`<a class="tab ${tab===id?'active':''}" href="#/cuenta?tab=${id}">${label}</a>`).join('')}</nav>${content}</div>`}
function adminNav(tab){return `<nav class="admin-nav" aria-label="Módulos administrativos">${[['dashboard','grid','Resumen'],['productos','box','Productos'],['pedidos','bag','Pedidos'],['clientes','user','Clientes'],['promociones','tag','Promociones'],['inventario','chart','Inventario'],['configuracion','settings','Configuración'],['actividad','clock','Actividad']].map(([id,i,t])=>`<a href="#/admin${id==='dashboard'?'':'/'+id}" class="${id===tab?'active':''}">${icon(i)}${t}</a>`).join('')}</nav>`}
function admin(){const tab=route().path.split('/')[2]||'dashboard';let content='';const active=state.products.filter(p=>p.active);if(tab==='dashboard'){const best={};state.orders.filter(o=>o.status!=='Cancelado DEMO').forEach(o=>o.lines.forEach(l=>{best[l.name]=(best[l.name]||0)+l.qty}));content=`<div class="admin-toolbar"><h2>Así va tu tienda DEMO</h2><a href="#/tienda" class="text-link">Ver tienda ${icon('arrow')}</a></div><div class="stats">${[['bag','Pedidos de prueba',state.orders.length],['chart','Ventas cobradas',money(0)],['user','Perfiles locales',state.profile?1:0],['box','Productos activos',active.length]].map(([i,t,n])=>`<div class="stat">${icon(i)}<small>${t}</small><strong>${n}</strong></div>`).join('')}</div><div class="two-columns"><section class="panel"><h3>Actividad reciente</h3>${state.audit.length?state.audit.slice(0,5).map(a=>`<div style="padding:10px 0;border-bottom:1px solid var(--line)"><strong style="font-size:12px">${esc(a.action)}</strong><div class="fine">${esc(a.actor)} · ${date(a.at)}</div></div>`).join(''):'<p class="fine">Todavía no hay cambios. Editá un producto o creá un pedido para empezar.</p>'}</section><section class="panel"><h3>Para revisar</h3><div class="summary-row"><span>Productos agotados</span><strong>${active.filter(p=>!p.stock).length}</strong></div><div class="summary-row"><span>Stock bajo (1 a 5)</span><strong>${active.filter(p=>p.stock>0&&p.stock<=5).length}</strong></div><div class="summary-row"><span>Solicitudes pendientes</span><strong>${state.wholesale.filter(w=>w.status==='Pendiente').length}</strong></div><a href="#/admin/clientes" class="text-link">Revisar solicitudes ${icon('arrow')}</a></section></div><section class="panel"><h3>Más pedidos en esta prueba</h3>${Object.keys(best).length?Object.entries(best).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([n,q])=>`<div class="summary-row"><span>${esc(n)}</span><strong>${q} unidades</strong></div>`).join(''):'<p class="fine">Este informe se completa con tus pedidos DEMO. No incluye ventas reales.</p>'}</section>`}else if(tab==='productos'){content=`<div class="admin-toolbar"><h2>Tu catálogo</h2><button class="btn small" data-action="edit-product" data-id="new">${icon('plus')}Nuevo producto</button></div><div class="table-wrap"><table><thead><tr><th>PRODUCTO DEMO</th><th>PRECIO</th><th>STOCK</th><th>ESTADO</th><th>ACCIÓN</th></tr></thead><tbody>${state.products.map(p=>`<tr><td><img src="${esc(p.image)}" alt=""><strong>${esc(p.name)}</strong><div class="fine">${esc(p.brand)} · ${esc(p.size)}</div></td><td>${money(p.price)}</td><td>${p.stock}</td><td>${statusPill(p.active?'Activo':'Inactivo')}</td><td><button class="btn small secondary" data-action="edit-product" data-id="${p.id}">${icon('edit')}Editar</button></td></tr>`).join('')}</tbody></table></div>`}else if(tab==='pedidos'){content=`<div class="admin-toolbar"><h2>Pedidos de prueba</h2><button class="btn small secondary" data-action="export-orders">${icon('download')}Exportar CSV</button></div>${notice('Los cambios de estado simulan la operación del negocio. Ningún pedido tiene un pago procesado. Se descuenta inventario DEMO al crearlo y se repone una sola vez al cancelarlo.')}${state.orders.length?state.orders.map(o=>orderCard(o,true)).join(''):empty('Todavía no hay pedidos DEMO.','Creá un pedido en la tienda y lo vas a encontrar acá.','/tienda','Probar una compra')}`}
else if(tab==='clientes'){content=`<div class="admin-toolbar"><h2>Clientes y mayoristas</h2></div><section class="panel"><h3>Perfil de este dispositivo</h3>${state.profile?`<div class="summary-row"><span>${esc(state.profile.name)}<br><small>${esc(state.profile.email)}</small></span>${statusPill(isWholesale()?'Mayorista':'Minorista')}</div><p class="fine">Pedidos vinculados a este correo de prueba: ${state.orders.filter(o=>o.customer.email===state.profile.email).length}</p>`:'<p class="fine">Creá un perfil DEMO desde Mi cuenta para probar el área de clientes.</p>'}</section><h3 style="margin-bottom:18px">Solicitudes mayoristas DEMO</h3>${state.wholesale.map(w=>`<article class="panel"><div class="order-header"><h3>${esc(w.business)}</h3>${statusPill(w.status)}</div><p class="fine">${esc(w.name)} · ${esc(w.email)}<br>${esc(w.businessType||'Rubro de ejemplo')} · ${esc(w.taxRef||'CUIT-DEMO')}</p><label class="field"><span>Estado de aprobación</span><select data-change="wholesale-status" data-id="${w.id}">${['Pendiente','Aprobada','Rechazada','Suspendida'].map(s=>`<option ${s===w.status?'selected':''}>${s}</option>`).join('')}</select></label><p class="fine">La aprobación habilita la lista mayorista únicamente en este entorno local DEMO.</p></article>`).join('')}`}
else if(tab==='promociones'){content=`<div class="admin-toolbar"><h2>Promociones DEMO</h2></div><form class="panel" data-form="promos"><h3>Cupón de ejemplo</h3><div class="form-grid">${field('Código','coupon',state.settings.coupon,'text',true)}${field('Descuento (%)','couponDiscount',Math.round(state.settings.couponDiscount*100),'number',true)}${field('Subtotal mínimo (ARS DEMO)','couponMin',state.settings.couponMin,'number',true)}</div><h3 class="mt">Escala por cantidad</h3><div class="form-grid">${field('Unidades combinadas desde','volumeQty',state.settings.volumeQty,'number',true)}${field('Descuento por cantidad (%)','volumeDiscount',Math.round(state.settings.volumeDiscount*100),'number',true)}</div><p class="fine">El descuento por cantidad se calcula primero; el cupón se aplica sobre ese resultado. Los combos y precios promocionales se editan desde Productos. Vigencias y combinaciones avanzadas quedan para la etapa comercial.</p><button class="btn">Guardar promociones DEMO</button></form>`}
else if(tab==='inventario'){content=`<div class="admin-toolbar"><h2>Inventario de prueba</h2><div class="actions"><button class="btn small secondary" data-action="export-inventory">${icon('download')}Exportar CSV</button><label class="btn small secondary" for="csv-file">Importar CSV</label><input type="file" id="csv-file" accept=".csv,text/csv" class="hide" data-change="import-inventory"></div></div>${notice('Importación CSV: columnas <strong>id,stock</strong>. Actualiza solo existencias de productos conocidos, valida el archivo completo y registra los cambios. No modifica precios. Excel: exportá primero como CSV UTF-8.')}<div class="table-wrap"><table><thead><tr><th>ID</th><th>PRODUCTO</th><th>STOCK DEMO</th><th>AJUSTAR</th></tr></thead><tbody>${state.products.map(p=>`<tr><td>${p.id}</td><td>${esc(p.name)}${!p.stock?'<br><span class="pill red">Agotado</span>':''}</td><td>${p.stock}</td><td><button class="btn small secondary" data-action="stock-adjust" data-id="${p.id}">${icon('edit')}Ajustar</button></td></tr>`).join('')}</tbody></table></div><section class="panel mt"><h3>Últimos movimientos</h3>${state.audit.filter(a=>/stock|inventario|pedido|cancel/i.test(a.action)).slice(0,10).map(a=>`<p class="fine">${date(a.at)} · ${esc(a.action)} · ${esc(a.actor)}</p>`).join('')||'<p class="fine">Sin movimientos todavía.</p>'}</section>`}
else if(tab==='configuracion'){content=`<div class="admin-toolbar"><h2>Configuración DEMO</h2></div><form class="panel" data-form="settings"><h3>Datos comerciales provisionales</h3><div class="form-grid">${field('Dirección provisoria','address',state.settings.contact.address,'text',true)}${field('Correo de ejemplo (.example o .invalid)','email',state.settings.contact.email,'email',true)}${field('Horarios de ejemplo','hours',state.settings.contact.hours,'text',true)}</div><h3 class="mt">Entrega y mayoristas</h3><div class="form-grid">${field('Costo de entrega (ARS DEMO)','shipping',state.settings.shipping,'number',true)}${field('Envío sin cargo desde (subtotal ARS)','freeShipping',state.settings.freeShipping,'number',true)}${field('Mínimo mayorista por producto','wholesaleMin',state.settings.wholesaleMin,'number',true)}${field('Zonas DEMO separadas por coma','coverage',state.settings.coverage.join(', '),'text',true)}</div><button class="btn">Guardar configuración</button></form><section class="panel"><h3>Pagos e integraciones</h3><p class="fine">Mercado Pago, correo transaccional, WhatsApp y cuentas comerciales: pendientes. Las claves se configurarán del lado del servidor. Este formulario nunca solicita ni guarda credenciales.</p><span class="pill orange">Pagos reales deshabilitados</span></section>`}
else if(tab==='actividad'){content=`<div class="admin-toolbar"><h2>Historial de cambios DEMO</h2><button class="btn small secondary" data-action="export-audit">${icon('download')}Exportar CSV</button></div>${notice('Registro local de los últimos 250 eventos. Identifica al perfil DEMO, fecha y acción. El registro de auditoría comercial deberá ser persistente y protegido en el servidor.')}<div class="table-wrap"><table><thead><tr><th>FECHA · ARGENTINA</th><th>PERFIL DEMO</th><th>ACCIÓN</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${date(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="3">Sin actividad registrada.</td></tr>'}</tbody></table></div>`}
else content=empty('Módulo no encontrado.','Volvé al resumen del panel.','/admin','Ver resumen');return `<div class="container">${crumb('Panel administrativo DEMO')}${pageHead('Todo en un mismo lugar.','Explorá la gestión diaria de Distribuidora Libertad con datos de prueba.')}${notice('<strong>Panel de demostración local.</strong> No es una administración comercial protegida. Sus cambios solo afectan este navegador. Los roles de propietario, técnico y empleados se implementarán con autorización en el servidor.','warning')}<div class="admin-layout">${adminNav(tab)}<div style="min-width:0">${content}</div></div></div>`}
function about(){return `<div class="container">${crumb('Sobre nosotros')}<div class="about-hero"><div><div class="eyebrow"><span class="dot"></span>DE SANTIAGO, PARA COMPARTIR</div><h1>Los buenos momentos<br>tienen algo en común.</h1><p>Un helado después de comer. Una merienda que se alarga. Ese gustito que hace más lindo el día.</p><p>Distribuidora Libertad comercializa helados en Santiago del Estero para familias y comercios. Este proyecto propone sumar una forma más simple de conocer el catálogo y hacer pedidos.</p><a class="btn" href="#/tienda">Conocé el catálogo DEMO ${icon('arrow')}</a></div><img src="/assets/vainilla.jpg" alt="Helado servido para compartir" loading="lazy"></div>${notice('Texto institucional provisional. No se atribuyen años de trayectoria, certificaciones ni compromisos comerciales no confirmados.')}<div class="info-grid">${[['heart','Cerca de vos','Una experiencia simple para elegir, consultar y volver a pedir.'],['snow','El frío importa','La logística comercial deberá validar conservación y transporte de congelados.'],['store','Junto a tu comercio','Una propuesta que contempla tanto compras familiares como abastecimiento mayorista.']].map(([i,t,d])=>`<div class="info-card">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div>`}
function contact(){const c=state.settings.contact;return `<div class="container">${crumb('Contacto')}${pageHead('Estamos cerca.','En esta versión, todos los canales de contacto son provisionales o están desactivados.')}<div class="contact-grid"><section class="panel"><h2>Distribuidora Libertad</h2>${[['pin','Ubicación',c.address],['clock','Horarios provisionales',c.hours],['mail','Correo de ejemplo',c.email],['phone','WhatsApp DEMO','Número pendiente · Canal desactivado']].map(([i,t,d])=>`<div class="contact-item">${icon(i)}<div><strong>${t}</strong><p>${esc(d)}</p></div></div>`).join('')}<button class="btn secondary" data-action="contact-demo">${icon('phone')}Consultar por WhatsApp · DEMO</button><p class="fine">No se abrirá ningún teléfono ni se enviará un mensaje.</p></section><div><div class="contact-map"><div>${icon('pin')}<h3>Santiago del Estero</h3><p>Ubicación exacta pendiente de confirmar.<br>Mapa ilustrativo, sin dirección comercial.</p></div></div><div class="panel mt"><h3>¿Querés abastecer tu comercio?</h3><p class="fine">Explorá la solicitud mayorista y las condiciones de ejemplo.</p><a href="#/mayoristas" class="text-link">Conocé la modalidad mayorista ${icon('arrow')}</a></div></div></div></div>`}
function help(){return `<div class="container legal">${crumb('Preguntas frecuentes')}${pageHead('Te damos una mano.','Todo lo que necesitás para explorar esta primera versión.')}<div class="faq">${[['¿Puedo comprar de verdad?','No. Esta versión permite probar un pedido sin cobro, envío ni reserva comercial. Todo el contenido está identificado como DEMO.'],['¿Dónde se guardan mis datos?','En el almacenamiento de este navegador. No se envían al negocio ni se sincronizan entre dispositivos. Usá únicamente datos ficticios.'],['¿Cómo pruebo los precios mayoristas?',`Creá un perfil DEMO, completá la solicitud mayorista y aprobala desde Panel DEMO → Clientes. Al comprar ${state.settings.wholesaleMin} unidades del mismo producto, el carrito utiliza el precio mayorista de prueba.`],['¿Cómo funcionan los descuentos?',`El descuento por volumen se activa desde ${state.settings.volumeQty} unidades combinadas. El cupón ${esc(state.settings.coupon)} se aplica desde ${money(state.settings.couponMin)} de subtotal y se calcula después del descuento por volumen. Condiciones de ejemplo.`],['¿Cómo se prueba la entrega?',`Elegí entrega en el checkout y una zona DEMO habilitada. Costo ${money(state.settings.shipping)}, sin cargo desde ${money(state.settings.freeShipping)} de subtotal. Fuera de cobertura no se puede confirmar.`],['¿Qué falta para abrir comercialmente?','Base de datos compartida, autenticación comercial, permisos del servidor, pagos y notificaciones verificadas, información oficial, fichas técnicas, revisión legal y validación logística.'],['¿Cómo reemplazamos imágenes y marca?','El logotipo está centralizado en assets/logo.svg, los colores en styles.css y los datos iniciales en data.js. El catálogo puede editarse desde el panel DEMO. El ZIP original se incorporará sin cambiar la lógica de compra.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`}
function legal(){return `<div class="container legal">${crumb('Privacidad y condiciones DEMO')}${pageHead('Una prueba, con información clara.')}${notice('Documento informativo provisional. No reemplaza los términos comerciales ni la política de privacidad que deberá revisar el negocio antes de operar.','warning')}<h2>Alcance de la demostración</h2><p>Los productos, marcas, precios, fotografías y condiciones de esta aplicación son ilustrativos. No hay aceptación de una venta comercial, cobro ni compromiso de entrega. Los cambios se realizan en el almacenamiento de tu navegador.</p><h2>Datos y servicios externos</h2><p>No ingreses información personal real. Los perfiles, direcciones y pedidos de prueba se guardan localmente y pueden eliminarse desde Mi cuenta → Restablecer demo. Las imágenes de producto se sirven junto con la aplicación. Las tipografías se solicitan a Google Fonts. La plataforma de alojamiento puede registrar información técnica y gestionar el acceso privado.</p><h2>Condiciones para la operación comercial</h2><p>Antes de recibir clientes reales se deberá completar la identidad del proveedor, datos fiscales, tratamiento de datos personales conforme a la Ley 25.326, información al consumidor conforme a la Ley 24.240 y normativa vigente, condiciones de entrega, cancelaciones, devoluciones y mecanismos de reclamo aplicables.</p><h2>Productos congelados</h2><p>Los ingredientes, alérgenos, conservación, transporte y especificaciones se confirmarán con cada proveedor. Esta versión no contiene fichas técnicas válidas para uso comercial.</p><a href="#/ayuda" class="btn secondary">Ver ayuda de la demostración ${icon('arrow')}</a></div>`}
function render(){const {path}=route();let body='';if(path==='/')body=home();else if(path==='/tienda')body=catalog();else if(path==='/ofertas')body=catalog(true);else if(path.startsWith('/producto/'))body=detail(path.split('/')[2]);else if(path==='/carrito')body=cartPage();else if(path==='/checkout')body=checkout();else if(path.startsWith('/pedido/'))body=confirmation(path.split('/')[2]);else if(path==='/cuenta')body=account();else if(path==='/mayoristas')body=wholesale();else if(path.startsWith('/admin'))body=admin();else if(path==='/nosotros')body=about();else if(path==='/contacto')body=contact();else if(path==='/ayuda')body=help();else if(path==='/legal')body=legal();else body=`<div class="container">${crumb('Página no encontrada')}${empty('Este camino se derritió.','Volvé al inicio para seguir explorando.','/','Volver al inicio','search')}</div>`;$('#app').innerHTML=header()+(!storageOK?'<div class="storage-warning">No se pudo guardar en este navegador. Los cambios pueden perderse.</div>':'')+`<main id="main" tabindex="-1" class="${path==='/'?'':'page-body'}">${body}</main>`+footer()+mobileNav();document.title=(path==='/'?'Un mundo de helados':path.startsWith('/admin')?'Panel DEMO':path==='/tienda'?'Todos los helados':path==='/ofertas'?'Ofertas DEMO':path==='/carrito'?'Tu carrito':path==='/checkout'?'Pedido DEMO':path==='/cuenta'?'Mi cuenta DEMO':'Explorá la tienda')+' · Distribuidora Libertad';}
function sync(){save();render();if(drawerOpen)drawCart(false)}
function add(id,qty=1){const p=state.products.find(p=>p.id===id&&p.active);if(!p||!p.stock){toast('Este producto no tiene stock DEMO.');return false}const current=state.cart.find(l=>l.id===id);const old=current?.qty||0;const next=Math.min(old+qty,p.stock);if(next===old){toast('Llegaste al stock disponible de este producto.');return false}if(current)current.qty=next;else state.cart.push({id,qty:next});sync();toast(next<old+qty?'Agregamos la cantidad disponible en stock.':'¡Un gustito más en tu carrito!');return true}
function closeOverlay(){const was=$('#overlay').innerHTML;$('#overlay').innerHTML='';document.body.style.overflow='';drawerOpen=false;if(was&&returnFocus?.isConnected)returnFocus.focus()}
function overlay(html){returnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close" aria-hidden="true"></div>${html}`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay button, #overlay input, #overlay a')?.focus(),0)}
function modal(title,body){drawerOpen=false;overlay(`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>${body}</section>`)}
function drawCart(first=true){const t=calc();const html=`<section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><h2 id="drawer-title">Tu carrito <span class="muted">(${t.count})</span></h2><button class="icon-btn" data-action="close" aria-label="Cerrar carrito">${icon('close')}</button></div><div class="drawer-body">${t.count?cartLines():empty('Falta tu helado favorito.','Elegí uno para empezar.','/tienda','Explorar helados')}</div>${t.count?`<div class="drawer-bottom"><div class="summary-row total"><span>Total DEMO</span><strong>${money(t.total)}</strong></div><p class="fine">Envío a calcular. Precios de ejemplo, sin cobros reales.</p><a class="btn full" href="#/carrito" data-action="close-link">Ver mi carrito ${icon('arrow')}</a><a class="btn full secondary" href="#/checkout" data-action="close-link">Continuar con el pedido</a></div>`:''}</section>`;if(first)overlay(html);else $('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close" aria-hidden="true"></div>${html}`;drawerOpen=true}
function productEditor(id){const p=id==='new'?{id:'new',name:'',brand:'Marca DEMO',flavor:'Vainilla',size:'Pote · 1 litro',price:0,wholesale:0,oldPrice:0,stock:0,active:true,category:'familiares',image:'/assets/vainilla.jpg',description:'Producto ficticio de demostración. Imagen ilustrativa del sabor servido.'}:state.products.find(p=>p.id===id);if(!p)return;modal(id==='new'?'Nuevo producto DEMO':'Editar producto DEMO',`<form data-form="product-editor" data-id="${p.id}"><div class="form-grid">${field('Nombre de ejemplo','name',p.name,'text',true)}${field('Marca ficticia','brand',p.brand,'text',true)}${field('Sabor','flavor',p.flavor,'text',true)}${field('Presentación','size',p.size,'text',true)}<label class="field"><span>Categoría</span><select name="category">${categories.slice(1).map(c=>`<option value="${c.id}" ${p.category===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label>${field('Stock DEMO','stock',p.stock,'number',true)}${field('Precio minorista (ARS)','price',p.price,'number',true)}${field('Precio mayorista (ARS)','wholesale',p.wholesale,'number',true)}${field('Precio anterior (0 = sin oferta)','oldPrice',p.oldPrice||0,'number',true)}<label class="field"><span>Fotografía ilustrativa</span><select name="image">${[['vainilla','Crema / vainilla servida'],['chocolate','Postre de chocolate'],['frutilla','Cucurucho frutilla / crema'],['dulce','Palitos de frutos rojos'],['familia','Palitos de mora'],['comercio','Crema con granas'],['palitos-frambuesa','Palitos de frambuesa']].map(([v,t])=>`<option value="/assets/${v}.jpg" ${p.image==='/assets/'+v+'.jpg'?'selected':''}>${t}</option>`).join('')}</select></label><label class="field span2"><span>Reemplazar por una foto propia (opcional)</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WebP. Máximo 1 MB. Se guarda solo en este navegador.</small></label><label class="field span2"><span>Descripción DEMO</span><textarea name="description" maxlength="1000" required>${esc(p.description)}</textarea></label></div><label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}>Producto activo en el catálogo</label><button class="btn full">Guardar producto DEMO</button></form>`)}
function download(filename,text,type='text/csv;charset=utf-8'){const b=new Blob([text],{type});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportCSV(name,headers,rows){download(name,'\uFEFF'+[headers,...rows].map(row=>row.map(csvEscape).join(',')).join('\r\n'));toast('Archivo DEMO exportado.')}
function positiveInt(value,min=0,max=10000000){const n=Number(value);if(String(value??'').trim()===''||!Number.isSafeInteger(n)||n<min||n>max)throw Error('Revisá los valores numéricos: deben ser enteros entre '+min+' y '+max+'.');return n}
function formObject(form){return Object.fromEntries(new FormData(form))}
function testEmail(email){return /@(example\.(com|org|net)|[^@]+\.(invalid|example))$/i.test(email)}
function requireDemoEmail(email){if(!testEmail(email))throw Error('Usá un correo de ejemplo, como cliente@example.invalid. No ingreses datos reales.');}
async function imageData(file){if(file.size>1024*1024)throw Error('La fotografía supera 1 MB. Elegí una versión más pequeña.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usá un archivo JPG, PNG o WebP.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('No pudimos leer la foto.'));r.readAsDataURL(file)})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='close-link'){closeOverlay();return}if(b.tagName==='BUTTON')e.preventDefault();if(a==='cart')drawCart();else if(a==='close')closeOverlay();else if(a==='add')add(id);else if(a==='favorite'){if(state.favorites.includes(id))state.favorites=state.favorites.filter(x=>x!==id);else state.favorites.push(id);sync();toast(state.favorites.includes(id)?'Guardado en tus favoritos.':'Quitado de favoritos.')}else if(a==='qty'){const line=state.cart.find(l=>l.id===id),p=state.products.find(p=>p.id===id);if(!line||!p)return;const next=line.qty+Number(b.dataset.delta);if(next>p.stock){toast('Llegaste al stock DEMO disponible.');return}if(next<=0)state.cart=state.cart.filter(l=>l.id!==id);else line.qty=next;sync()}else if(a==='remove'){state.cart=state.cart.filter(l=>l.id!==id);sync();toast('Producto quitado del carrito.')}else if(a==='load'){const y=window.scrollY;pageLimit+=9;render();window.scrollTo(0,y)}else if(a==='detail-minus'||a==='detail-plus'){const i=$('#detail-qty');if(i)i.value=Math.max(1,Math.min(Number(i.max),Number(i.value)+(a==='detail-plus'?1:-1)))}else if(a==='contact-demo')toast('WhatsApp está desactivado. Falta confirmar el número comercial.');else if(a==='demo-info')modal('Una tienda para explorar.',`<p>Esta es una primera versión funcional con contenido ficticio y provisional.</p><ul class="fine"><li>Probá búsqueda, filtros, favoritos y carrito.</li><li>Creá pedidos sin cobro y consultalos en Mi cuenta.</li><li>Editá productos y aprobá solicitudes desde el panel DEMO.</li><li>Todo se guarda en este navegador. No hay sincronización ni cuentas comerciales activas.</li></ul><a href="#/ayuda" class="btn" data-action="close-link">Ver guía de la demostración ${icon('arrow')}</a>`);else if(a==='edit-product')productEditor(id);else if(a==='stock-adjust'){const p=state.products.find(p=>p.id===id);modal('Ajustar stock DEMO',`<form data-form="stock" data-id="${id}"><p class="fine">${esc(p.name)} · Stock actual: ${p.stock}</p>${field('Nuevo stock','stock',p.stock,'number',true)}${field('Motivo del ajuste','reason','','text',true,'Ej.: reposición DEMO')}<button class="btn full">Guardar ajuste DEMO</button></form>`)}else if(a==='delete-address'){state.addresses.splice(Number(b.dataset.index),1);save();render();toast('Dirección eliminada.')}else if(a==='reorder'){const o=state.orders.find(o=>o.id===id);let missed=0;o.lines.forEach(l=>{const p=state.products.find(p=>p.id===l.id&&p.active);if(!p||!p.stock){missed++;return}const c=state.cart.find(c=>c.id===l.id);const qty=Math.min((c?.qty||0)+l.qty,p.stock);if(c)c.qty=qty;else state.cart.push({id:l.id,qty});if(qty<l.qty)missed++});sync();drawCart();toast(missed?'Revisá el carrito: algunos productos cambiaron de disponibilidad.':'Pedido agregado al carrito con precios y stock actuales.')}else if(a==='logout'){state.profile=null;save();render();toast('Perfil DEMO cerrado. Los datos locales se conservan.')}else if(a==='export-backup')download('libertad-copia-demo.json',JSON.stringify(state,null,2),'application/json');else if(a==='reset'){modal('¿Restablecer la demostración?',`<p class="fine">Se borrarán el perfil, los pedidos, las direcciones y los cambios locales del panel. El catálogo vuelve a sus datos iniciales.</p><p class="fine">Podés exportar una copia antes desde Mi cuenta.</p><button class="btn red full" data-action="confirm-reset">Borrar datos locales y restablecer</button>`)}else if(a==='confirm-reset'){try{localStorage.removeItem(STORE)}catch{}closeOverlay();location.reload()}else if(a==='export-inventory')exportCSV('libertad-inventario-demo.csv',['id','stock','nombre','precio_minorista','precio_mayorista'],state.products.map(p=>[p.id,p.stock,p.name,p.price,p.wholesale]));else if(a==='export-orders')exportCSV('libertad-pedidos-demo.csv',['pedido','fecha','cliente_demo','correo_demo','modalidad','estado','pago','total_ars'],state.orders.map(o=>[o.number,o.created,o.customer.name,o.customer.email,o.delivery,o.status,'No procesado',o.total]));else if(a==='export-audit')exportCSV('libertad-actividad-demo.csv',['fecha','perfil_demo','accion'],state.audit.map(a=>[a.at,a.actor,a.action]));});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form;const d=formObject(form);try{
if(type==='search'){pageLimit=9;goto('/tienda'+(d.q.trim()?'?q='+encodeURIComponent(d.q.trim()):''))}
else if(type==='filters'){pageLimit=9;const params=new URLSearchParams();for(const[k,v]of Object.entries(d))if(v&&!(k==='cat'&&v==='todos'))params.set(k,v);goto(form.dataset.base+'?'+params)}
else if(type==='add-product'){add(form.dataset.id,positiveInt(d.qty,1,100000))}
else if(type==='coupon'){const c=d.coupon.trim().toUpperCase();if(!c){state.coupon='';sync();toast('Cupón quitado.')}else if(c!==state.settings.coupon)toast('Ese cupón no está disponible en esta DEMO.');else if(calc().subtotal<state.settings.couponMin)toast('El cupón requiere un subtotal de '+money(state.settings.couponMin)+'.');else{state.coupon=c;sync();toast('¡Cupón DEMO aplicado!')}}
else if(type==='profile'){requireDemoEmail(d.email);state.profile={name:d.name.trim(),email:d.email.trim().toLowerCase()};audit('Perfil DEMO guardado');save();render();toast('Tu perfil DEMO está listo.')}
else if(type==='address'){state.addresses.push({label:d.label.trim(),street:d.street.trim(),zone:d.zone});save();render();toast('Dirección de ejemplo guardada.')}
else if(type==='wholesale'){if(!state.profile)throw Error('Primero creá un perfil DEMO.');if(state.wholesale.some(w=>w.email===state.profile.email))throw Error('Ya existe una solicitud para este perfil.');state.wholesale.unshift({...d,id:crypto.randomUUID(),name:state.profile.name,email:state.profile.email,status:'Pendiente',created:new Date().toISOString()});audit('Solicitud mayorista DEMO creada');save();render();toast('Solicitud guardada como pendiente.')}
else if(type==='checkout'){requireDemoEmail(d.email);if(d.delivery==='delivery'&&(!d.street.trim()||!state.settings.coverage.includes(d.zone)))throw Error('Completá la dirección y elegí una zona DEMO habilitada. No se puede confirmar fuera de cobertura.');const current=calc(d.delivery);if(!current.lines.length)throw Error('El carrito ya no tiene productos disponibles.');if(state.cart.some(l=>{const p=state.products.find(p=>p.id===l.id&&p.active);return !p||p.stock<l.qty}))throw Error('Cambió el stock DEMO. Revisá tu carrito antes de continuar.');if(!d.consent)throw Error('Confirmá que entendés el alcance de esta prueba.');const o={id:crypto.randomUUID(),number:'DL-DEMO-'+String(state.orders.length+1).padStart(4,'0'),created:new Date().toISOString(),customer:d,delivery:d.delivery,status:'Recibido DEMO',payment:'No procesado',...current,inventoryReleased:false};state.orders.unshift(o);current.lines.forEach(l=>{const p=state.products.find(p=>p.id===l.id);p.stock-=l.qty});audit('Pedido '+o.number+' creado; stock DEMO descontado');state.cart=[];state.coupon='';save();goto('/pedido/'+o.id)}
else if(type==='product-editor'){const price=positiveInt(d.price,1),wholesalePrice=positiveInt(d.wholesale,1),stock=positiveInt(d.stock),oldPrice=positiveInt(d.oldPrice);if(wholesalePrice>price)throw Error('El precio mayorista debe ser igual o menor al minorista.');if(oldPrice&&oldPrice<=price)throw Error('El precio anterior debe superar al precio actual, o ser cero.');const existing=state.products.find(p=>p.id===form.dataset.id);const photo=new FormData(form).get('photo');const image=photo?.size?await imageData(photo):existing?.image.startsWith('data:')&&d.image==='/assets/vainilla.jpg'?existing.image:d.image;const p={...existing,id:existing?.id||'p-'+crypto.randomUUID().slice(0,8),name:d.name.trim(),brand:d.brand.trim(),flavor:d.flavor.trim(),size:d.size.trim(),category:d.category,price,wholesale:wholesalePrice,oldPrice:oldPrice||undefined,badge:oldPrice?Math.round((1-price/oldPrice)*100)+'% OFF':undefined,stock,active:!!d.active,image,description:d.description.trim()};if(existing)state.products=state.products.map(x=>x.id===existing.id?p:x);else state.products.push(p);audit((existing?'Producto editado: ':'Producto creado: ')+p.name);save();closeOverlay();render();toast('Producto DEMO guardado.')}
else if(type==='stock'){const p=state.products.find(p=>p.id===form.dataset.id);const stock=positiveInt(d.stock);audit('Ajuste de stock '+p.name+': '+p.stock+' → '+stock+'. Motivo: '+d.reason.trim());p.stock=stock;save();closeOverlay();render();toast('Stock DEMO actualizado.')}
else if(type==='promos'){const coupon=d.coupon.trim().toUpperCase();if(!/^[A-Z0-9_-]{3,25}$/.test(coupon))throw Error('El cupón debe tener entre 3 y 25 letras, números, guiones o guiones bajos.');const values={coupon,couponDiscount:positiveInt(d.couponDiscount,0,80)/100,couponMin:positiveInt(d.couponMin),volumeQty:positiveInt(d.volumeQty,1,10000),volumeDiscount:positiveInt(d.volumeDiscount,0,80)/100};Object.assign(state.settings,values);state.coupon='';audit('Promociones y escalas DEMO actualizadas');save();render();toast('Promociones guardadas.')}
else if(type==='settings'){requireDemoEmail(d.email);const coverage=d.coverage.split(',').map(s=>s.trim()).filter(Boolean);if(!coverage.length)throw Error('Configurá al menos una zona de ejemplo.');state.settings.contact={address:d.address.trim(),email:d.email.trim(),hours:d.hours.trim()};Object.assign(state.settings,{shipping:positiveInt(d.shipping),freeShipping:positiveInt(d.freeShipping),wholesaleMin:positiveInt(d.wholesaleMin,1,10000),coverage});audit('Configuración comercial DEMO actualizada');save();render();toast('Configuración guardada.')}
}catch(err){if(type==='checkout'){$('#checkout-error').textContent=err.message;$('#checkout-error').scrollIntoView({block:'center',behavior:'smooth'})}toast(err.message||'No pudimos completar la acción. Revisá los datos.')}});
document.addEventListener('change',async e=>{const el=e.target;if(el.name==='delivery'&&route().path==='/checkout'){const delivery=el.value==='delivery';$('#delivery-fields').classList.toggle('hide',!delivery);$('[name="street"]').required=delivery;$('[name="zone"]').required=delivery;$('#checkout-summary').innerHTML=summary(el.value,false);return}const type=el.dataset.change;if(type==='sort'){const r=route();r.params.set('sort',el.value);pageLimit=9;goto(r.path+'?'+r.params)}else if(type==='address'){const a=state.addresses[Number(el.value)];if(a&&el.value!==''){$('[name="street"]').value=a.street;$('[name="zone"]').value=a.zone;toast('Dirección DEMO completada. Elegí entrega para utilizarla.')}}else if(type==='wholesale-status'){const w=state.wholesale.find(w=>w.id===el.dataset.id);w.status=el.value;audit('Cuenta mayorista '+w.business+': '+w.status);sync();toast('Estado mayorista DEMO actualizado.')}else if(type==='order-status'){const o=state.orders.find(o=>o.id===el.dataset.id);if(o.inventoryReleased){el.value=o.status;toast('Un pedido cancelado queda cerrado. Creá otro pedido DEMO para continuar.');return}if(el.value==='Cancelado DEMO'){o.lines.forEach(l=>{const p=state.products.find(p=>p.id===l.id);if(p)p.stock+=l.qty});o.inventoryReleased=true;audit('Pedido '+o.number+' cancelado; stock DEMO repuesto')}o.status=el.value;audit('Estado del pedido '+o.number+': '+o.status);save();render();toast('Estado del pedido actualizado.')}else if(type==='import-inventory'){const file=el.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('El CSV supera 1 MB.');const rows=parseCSV(await file.text());if(rows.length<2)throw Error('El CSV necesita encabezados y al menos un producto.');const headers=rows.shift().map(x=>x.trim().toLowerCase());const idCol=headers.indexOf('id'),stockCol=headers.indexOf('stock');if(idCol<0||stockCol<0)throw Error('El CSV debe contener las columnas id y stock.');const seen=new Set();const updates=rows.map((r,i)=>{const id=r[idCol]?.trim(),stock=positiveInt(r[stockCol]);if(!state.products.some(p=>p.id===id))throw Error('Producto desconocido en fila '+(i+2)+': '+id);if(seen.has(id))throw Error('ID repetido: '+id);seen.add(id);return{id,stock}});modal('Revisar importación DEMO',`<p class="fine">Se actualizará el stock de ${updates.length} productos. Todos los datos se validaron. Esta acción solo afecta este navegador.</p><div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>ACTUAL</th><th>NUEVO</th></tr></thead><tbody>${updates.map(u=>{const p=state.products.find(p=>p.id===u.id);return `<tr><td>${esc(p.name)}</td><td>${p.stock}</td><td>${u.stock}</td></tr>`}).join('')}</tbody></table></div><button class="btn full mt" id="confirm-import">Aplicar importación DEMO</button>`);$('#confirm-import').onclick=()=>{updates.forEach(u=>{const p=state.products.find(p=>p.id===u.id);audit('Importación inventario '+p.id+': '+p.stock+' → '+u.stock);p.stock=u.stock});save();closeOverlay();render();toast('Inventario DEMO importado correctamente.')};}catch(err){toast(err.message)}el.value=''}});
document.addEventListener('keydown',e=>{if(!$('#overlay').innerHTML)return;if(e.key==='Escape'){closeOverlay();return}if(e.key==='Tab'){const elements=[...$('#overlay').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea')].filter(x=>x.offsetParent!==null);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{closeOverlay();pageLimit=9;render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true})});
window.addEventListener('storage',e=>{if(e.key===STORE){const next=read();if(next){state=next;render();if(drawerOpen)drawCart(false);toast('Datos DEMO actualizados desde otra pestaña.')}}});
render();
